#!/usr/bin/env python3

from django.utils.html import urlize

def test_comprehensive():
    """Test various edge cases for the urlize function with HTML entities"""

    test_cases = [
        # Original issue
        {
            'input': 'Search for google.com/?q=1&lt! and see.',
            'expected': 'Search for <a href="http://google.com/?q=1%3C">google.com/?q=1&lt</a>! and see.',
            'description': 'Original issue: &lt entity with trailing punctuation'
        },

        # More HTML entities with trailing punctuation
        {
            'input': 'Visit http://example.com/?param=1&gt;.',
            'expected': 'Visit <a href="http://example.com/?param=1%3E">http://example.com/?param=1&gt</a>.',
            'description': '&gt entity with trailing punctuation'
        },

        {
            'input': 'Check http://test.com/?a=1&amp;b=2!',
            'expected': 'Check <a href="http://test.com/?a=1&b=2">http://test.com/?a=1&amp;b=2</a>!',
            'description': '&amp entity with trailing punctuation'
        },

        {
            'input': 'Go to http://site.com/?q=&quot;test&quot;.',
            'expected': 'Go to <a href="http://site.com/?q=%22test%22">http://site.com/?q=&quot;test&quot;</a>.',
            'description': '&quot entity with trailing punctuation'
        },

        # Multiple entities
        {
            'input': 'See http://example.com/?a=1&lt;&amp;&gt;!',
            'expected': 'See <a href="http://example.com/?a=1%3C&%3E">http://example.com/?a=1&lt;&amp;&gt;</a>!',
            'description': 'Multiple entities with trailing punctuation'
        },

        # Entities without trailing punctuation (should still work)
        {
            'input': 'Visit http://example.com/?param=1&lt;',
            'expected': 'Visit <a href="http://example.com/?param=1%3C">http://example.com/?param=1&lt;</a>',
            'description': 'Entity without trailing punctuation'
        },

        # Regular URLs without entities (should still work)
        {
            'input': 'Visit http://example.com/path!',
            'expected': 'Visit <a href="http://example.com/path">http://example.com/path</a>!',
            'description': 'Regular URL with trailing punctuation'
        },

        # Numeric character references
        {
            'input': 'Check http://test.com/?q=&#60;test&#62;.',
            'expected': 'Check <a href="http://test.com/?q=%3Ctest%3E">http://test.com/?q=&#60;test&#62;</a>.',
            'description': 'Numeric character references with trailing punctuation'
        },

        # Mixed case
        {
            'input': 'Go to http://example.com/?a=1&LT;test&GT;!',
            'expected': 'Go to <a href="http://example.com/?a=1%3Ctest%3E">http://example.com/?a=1&LT;test&GT;</a>!',
            'description': 'Mixed case entities with trailing punctuation'
        },
    ]

    all_passed = True
    for i, test_case in enumerate(test_cases, 1):
        input_text = test_case['input']
        expected = test_case['expected']
        description = test_case['description']

        actual = urlize(input_text)
        passed = actual == expected
        all_passed = all_passed and passed

        print(f"Test {i}: {description}")
        print(f"Input:    {repr(input_text)}")
        print(f"Expected: {repr(expected)}")
        print(f"Actual:   {repr(actual)}")
        print(f"Result:   {'PASS' if passed else 'FAIL'}")
        print()

    print(f"Overall result: {'ALL TESTS PASSED' if all_passed else 'SOME TESTS FAILED'}")
    return all_passed

if __name__ == "__main__":
    test_comprehensive()

